static bool sh0(void) { return DN("mag.mOn"); }
static bool sh1(void) { return DN("mag.mOn") && (DS_IS("mag.mtype", "carousel")); }
static bool sh2(void) { return DN("mag.mOn") && (DS_IS("mag.mtype", "carousel") || DS_IS("mag.mtype", "chain")); }
static bool sh3(void) { return DN("mag.mOn") && (DS_IS("mag.mtype", "linear")); }
static bool sh4(void) { return !DN("mag.mOn") || !DN("mag.atcOn"); }
static bool sh5(void) { return DS_IS("net.mode", "static"); }
static bool sh6(void) { return DN("net.shOn"); }
static bool sh7(void) { return DN("net.shOn") && DS_IS("net.shType", "smb"); }
static bool sh8(void) { return DS_IS("mach.type", "laser"); }
static bool sh9(void) { return DS_IS("mach.type", "mill"); }
static bool sh10(void) { return DS_IS("mach.type", "plasma"); }
static bool sh11(void) { return DS_IS("mach.type", "lathe"); }
static bool sh12(void) { return DS_IS("sp.spCtl", "modbus"); }
static bool sh13(void) { return DS_IS("sp.spCtl", "modbus") && DS_IS("sp.spVfd", "generic"); }
static bool sh14(void) { return DS_IS("sp.spCtl", "pwm"); }
static bool sh15(void) { return DS_IS("sp.spWait", "time"); }
static bool sh16(void) { return DN("sp.spEnc"); }
static bool sh17(void) { return DS_IS("prb.prMount", "fixed"); }
static bool sh18(void) { return DS_IS("prb.prMount", "fixed") && DN("prb.prDep") > 0; }
static bool sh19(void) { return DN("lube.luOn"); }
static bool sh20(void) { return DN("lube.luOn") && DS_IS("lube.luMode", "time"); }
static bool sh21(void) { return DN("lube.luOn") && DS_IS("lube.luMode", "dist"); }

